import {confirmationOfferReviews} from './confirmation-offer-review-data.js';
import {careerCheckSpec,updateCareerCheck} from './career-check-questions.js';
import {planMatchCandidates} from './plan-matches.js';
export const reviewJudgmentLabels={'strong-interest':'Strong interest · confidence check','plausible-transfer':'Plausible transfer · clarify the role','domain-gap':'Domain interest not established','expressed-conflict':'Preference conflict to discuss'};
export function offerReviewsFor(id,privateReviews=[]){return id.startsWith('private-')?(Array.isArray(privateReviews)?privateReviews:[]).filter(r=>r.modelId===id):confirmationOfferReviews.filter(r=>r.modelId===id);}
export function offerReviewFor(id,careerId,privateReviews=[]){return offerReviewsFor(id,privateReviews).find(r=>r.careerId===careerId)||null;}
export function offerFollowupPrompts(id,careerId,privateReviews=[]){const r=offerReviewFor(id,careerId,privateReviews);return r?Object.fromEntries([[r.primaryQuestionId,r.followUpQuestion],...r.remainingQuestionPrompts.map(q=>[q.questionId,q.prompt])]):{};}
// These are explicit hypothetical direct responses, never replacements for replay inputs.
export function confirmationOfferReview(state,modelId,row,privateReviews=[]){const review=offerReviewFor(modelId,row.id,privateReviews);if(!review)return null;if(!review.coreAnswerSnapshot.every(a=>row.confirmation?.questions.some(q=>q.id===a.questionId&&(q.answer?.response||'not-asked')===a.response&&(q.answer?.confidence||null)===a.confidence)))return null;
 const unresolved=(row.confirmation?.questions||[]).filter(q=>q.answer?.response!=='yes'||q.answer?.source==='profile-inferred'&&q.answer?.confidence!=='high'),remaining=review.remainingQuestionPrompts.filter(q=>unresolved.some(u=>u.id===q.questionId)),spec=careerCheckSpec(row.id,{coreVersion:state._coreWorkVersion});
 if(!unresolved.some(q=>q.id===review.primaryQuestionId))throw Error('Reviewed follow-up no longer matches its frozen unresolved question.');
 const hypothetical=ids=>{const copy=structuredClone(state);for(const id of ids)if(!updateCareerCheck(copy,{careerId:row.id,questionId:id,optionId:'yes'}))throw Error('Invalid hypothetical follow-up.');const result=planMatchCandidates(copy);return {inTop:result.top.some(r=>r.id===row.id),stillPending:result.needsConfirmation.some(r=>r.id===row.id)};};
 return {...review,label:reviewJudgmentLabels[review.judgment],unresolvedCount:unresolved.length,remainingQuestionPrompts:remaining,nextIndex:spec.questions.findIndex(q=>q.id===review.primaryQuestionId),originalQuestions:unresolved.map(q=>({questionId:q.id,activity:q.activity,source:q.source,response:q.answer?.response||'not-asked',confidence:q.answer?.confidence||null})),ifOnlyNextYes:hypothetical([review.primaryQuestionId]),ifAllListedYes:hypothetical(unresolved.map(q=>q.id)),simulationNotice:'Hypothetical direct Yes answers under the current matching rules; no answer is saved and no training, admission or career choice is implied.'};
}
export function confirmationReviewSummary(rows){const reviewed=rows.flatMap(m=>(m.needsConfirmation||[]).filter(r=>r.offerReview).map(r=>({m,r}))),count=fn=>reviewed.filter(fn).length;return {offers:reviewed.length,models:new Set(reviewed.map(x=>x.m.id)).size,strongInterest:count(x=>x.r.offerReview.judgment==='strong-interest'),plausibleTransfer:count(x=>x.r.offerReview.judgment==='plausible-transfer'),domainGap:count(x=>x.r.offerReview.judgment==='domain-gap'),expressedConflict:count(x=>x.r.offerReview.judgment==='expressed-conflict'),degree:count(x=>x.r.routes.some(r=>['college','graduate'].includes(r.key))),confidenceOnly:count(x=>x.r.offerReview.confidenceOnly),oneQuestion:count(x=>x.r.offerReview.unresolvedCount===1),twoQuestions:count(x=>x.r.offerReview.unresolvedCount===2)};}
